from urllib.parse import urljoin


_STRIP_CHARS = " \t\n\r\f"


def _clean_url(value):
    # Browsers strip leading/trailing ASCII whitespace and remove tabs/newlines.
    if value is None:
        value = ""
    value = value.strip(_STRIP_CHARS)
    for ch in ("\t", "\n", "\r"):
        value = value.replace(ch, "")
    return value


def _first_attr(attrs, name):
    # In HTML the first occurrence of a duplicated attribute wins.
    for key, value in attrs:
        if key == name:
            return True, value
    return False, None


class _LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hrefs = []
        self.base_href = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == "a":
            found, value = _first_attr(attrs, "href")
            if found:
                self.hrefs.append(_clean_url(value))
        elif tag == "base" and self.base_href is None:
            found, value = _first_attr(attrs, "href")
            if found:
                self.base_href = _clean_url(value)


def extract_page_links(html, base_url):
    parser = _LinkParser()
    parser.feed(html or "")
    parser.close()

    effective_base = base_url
    if parser.base_href is not None:
        # A <base href> sets the document base URL (resolved against the page URL).
        effective_base = urljoin(base_url, parser.base_href)

    return [urljoin(effective_base, href) for href in parser.hrefs]

